def api_keys_list(api_key, status=None, name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0326000" if __import__("os").path.isdir("./environment_mix/0326000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if not isinstance(api_key, str) or api_key == "":
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "name_prefix must be a string", field="name_prefix")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    api_keys = _load("api_keys.json")

    # Authenticate explicit credential: match by id OR by client-visible value against key_hash using sha256(token)
    token_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
    caller = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key or k.get("key_hash") == token_hash:
            caller = k
            break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    # Pagination cursor: base64 JSON {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Visibility: this simple service exposes all keys once authenticated.
    rows = [k for k in api_keys if isinstance(k, dict)]

    # Filters
    if status is not None:
        rows = [k for k in rows if k.get("status") == status]
    if name_prefix is not None:
        rows = [k for k in rows if isinstance(k.get("name"), str) and k.get("name", "").startswith(name_prefix)]

    # Sort stable by created_at then id
    def _k(r):
        return (r.get("created_at") or "", r.get("id") or "")
    rows.sort(key=_k)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Update last_used_at on successful authentication
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    caller["last_used_at"] = now
    caller["updated_at"] = now
    _save("api_keys.json", api_keys)

    # Never return secret material; return key metadata/policy
    def _redact(k):
        kk = dict(k)
        kk.pop("key_hash", None)
        return kk

    return {
        "data": [_redact(k) for k in page],
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def api_keys_get(api_key, id, **_extra):
