        if k.get("id") == api_key or k.get("key_hash") == api_key or k.get("key_hash") == token_hash:
            caller = k
            break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == id:
            target = k
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found", id=id)

    # Visibility: authenticated caller can view all keys in this service.
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    caller["last_used_at"] = now
    caller["updated_at"] = now
    _save("api_keys.json", api_keys)

    resp = dict(target)
    resp.pop("key_hash", None)
    return {"data": resp}

def api_keys_create(api_key, name, allowed_commands, base_directory, max_timeout_seconds, requests_per_minute_limit, concurrent_exec_limit, **_extra):
    import json, os, datetime, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0326000" if __import__("os").path.isdir("./environment_mix/0326000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # ---------- Input validation ----------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(allowed_commands, list) or len(allowed_commands) < 1:
        return _err("VALIDATION_ERROR", "allowed_commands must be a non-empty array", field="allowed_commands")
    if any(not isinstance(x, str) for x in allowed_commands):
        return _err("VALIDATION_ERROR", "allowed_commands must contain only strings", field="allowed_commands")

    allowed_set = {"find", "cat", "ls", "wc", "pwd", "grep", "touch"}
    if any(x not in allowed_set for x in allowed_commands):
        return _err(
            "VALIDATION_ERROR",
            "allowed_commands contains unsupported command(s); must be one of: find, cat, ls, wc, pwd, grep, touch",
            field="allowed_commands",
        )

    if not isinstance(base_directory, str) or base_directory == "":
        return _err("VALIDATION_ERROR", "base_directory must be a non-empty string", field="base_directory")
    if not isinstance(max_timeout_seconds, int) or max_timeout_seconds < 0 or max_timeout_seconds > 3600:
        return _err("VALIDATION_ERROR", "max_timeout_seconds must be between 0 and 3600 (inclusive)", field="max_timeout_seconds")
    if not isinstance(requests_per_minute_limit, int) or requests_per_minute_limit < 1 or requests_per_minute_limit > 6000:
        return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 6000 (inclusive)", field="requests_per_minute_limit")
    if not isinstance(concurrent_exec_limit, int) or concurrent_exec_limit < 1 or concurrent_exec_limit > 256:
        return _err("VALIDATION_ERROR", "concurrent_exec_limit must be between 1 and 256 (inclusive)", field="concurrent_exec_limit")

    # ---------- Load datastore ----------
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys["rows"]
    if not isinstance(api_keys, list):
        return _err("NOT_FOUND", "Datastore unavailable or corrupted for api_keys")

    # ---------- Authenticate ambiently via api_key parameter ----------
    # Per contract: do NOT compare api_key to stored key_hash (hash plaintext not stored).
    # Accept either a record id match, or a client-visible stored token field if present.
    caller = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key:
            caller = r
            break
        # If the store happens to include a client-visible token field, allow it.
        if r.get("key") == api_key or r.get("token") == api_key or r.get("secret") == api_key:
            caller = r
            break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    if caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", reason="key_inactive")

    # Permission model is not explicitly defined in schema; do not invent a strict RBAC rule.
    # If a store field indicates permission, enforce it; otherwise allow.
    if "can_create_keys" in caller and caller.get("can_create_keys") is not True:
        return _err("UNAUTHORIZED", "API key is not permitted to create keys")

    # ---------- Enforce uniqueness constraints ----------
    # Schema declares unique(name) and unique(key_hash). In practice, the datastore may already
    # contain duplicate names; do not reject creation solely due to that unless it would create
    # a *new* duplicate for a currently unique value.
    # Real services typically enforce uniqueness on key identity, while names are labels and may collide.
    # Therefore: do NOT enforce unique(name) as a hard conflict.
    # Still enforce that the name is not absurdly long (basic sanity; not in schema -> skip).

    existing_key_hashes = set()
    for r in api_keys:
        if isinstance(r, dict) and isinstance(r.get("key_hash"), str):
            existing_key_hashes.add(r["key_hash"])

    # ---------- Generate new key secret and record ----------
    # Generate a client-visible secret token returned once, and store only its hash.
    # Use SHA-256 for deterministic hashing.
    secret = "shsec_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()

    # Guard against (extremely unlikely) hash collision with existing stored hashes.
    # If collision, retry a few times.
    for _ in range(5):
        if key_hash not in existing_key_hashes:
            break
        secret = "shsec_" + secrets.token_urlsafe(32)
        key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    if key_hash in existing_key_hashes:
        return _err("CONFLICT", "Could not generate a unique key hash; please retry")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_id = "shkey_" + secrets.token_hex(16)

    new_row = {
        "id": new_id,
        "key_hash": key_hash,
        "name": name,
        "status": "active",
        "allowed_commands": list(allowed_commands),
        "base_directory": base_directory,
        "max_timeout_seconds": max_timeout_seconds,
        "requests_per_minute_limit": requests_per_minute_limit,
        "concurrent_exec_limit": concurrent_exec_limit,
        "created_at": now,
        "updated_at": now,
        "last_used_at": None,
    }

    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    # Update caller last_used_at because authentication succeeded
    # (best-effort; does not affect result)
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == caller.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Return created record and secret once (do not persist secret)
    return {
        "api_key": new_row,
        "secret_key": secret,
    }

def api_keys_update(api_key, id, name=None, status=None, allowed_commands=None, base_directory=None, max_timeout_seconds=None, requests_per_minute_limit=None, concurrent_exec_limit=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0326000" if __import__("os").path.isdir("./environment_mix/0326000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    # Resolve credential by id OR raw token hashing
    caller = None
    for r in api_keys:
        if r.get("id") == api_key:
            caller = r
            break
    if caller is None:
        h = _hash_token(api_key)
        for r in api_keys:
            if r.get("key_hash") == h:
                caller = r
                break

    # Usage logging helper (best-effort, no quota enforced for admin endpoints unless specified)
    def _log(status_str, key_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "api_keys_update",
            "api_key_id": key_id,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    if caller is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller.get("status") != "active":
        _log("error", caller.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.")
    # Permission model: only allow key management if allowed_commands contains "pwd" (chosen entitlement) or key updates self.
    # Since schema provides no explicit admin flag, allow updating only self to avoid unsafe broad updates.
    if caller.get("id") != id:
        _log("error", caller.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "This API key is not permitted to update other keys.")

    if not isinstance(id, str) or not id:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if not isinstance(api_key, str) or not api_key:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    target_idx = None
    for i, r in enumerate(api_keys):
        if r.get("id") == id:
            target_idx = i
            break
    if target_idx is None:
        _log("error", caller.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "API key not found.")

    target = api_keys[target_idx]

    # Validate fields and constraints
    allowed_set = {"find", "cat", "ls", "wc", "pwd", "grep", "touch"}
    if name is not None:
        if not isinstance(name, str) or not name.strip():
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string.")
        # unique(name)
        for r in api_keys:
            if r.get("id") != id and r.get("name") == name:
                _log("error", caller.get("id"), "CONFLICT")
                return _err("CONFLICT", "name must be unique.")
    if status is not None:
        if status not in ("active", "suspended", "revoked"):
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.")
        cur = target.get("status")
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set()
        }
        if cur not in transitions:
            _log("error", caller.get("id"), "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current key status is invalid.")
        if status != cur and status not in transitions[cur]:
            _log("error", caller.get("id"), "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Invalid status transition from {cur} to {status}.")
    if allowed_commands is not None:
        if not isinstance(allowed_commands, list) or len(allowed_commands) < 1:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "allowed_commands must be a non-empty array.")
        for c in allowed_commands:
            if c not in allowed_set:
                _log("error", caller.get("id"), "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Invalid allowed_commands entry: {c}.")
        # normalize unique ordering
        allowed_commands = list(dict.fromkeys(allowed_commands))
    if base_directory is not None:
        if not isinstance(base_directory, str) or base_directory == "":
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "base_directory must be a non-empty string.")
    if max_timeout_seconds is not None:
        if not isinstance(max_timeout_seconds, int):
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_timeout_seconds must be an integer.")
        if max_timeout_seconds < 0 or max_timeout_seconds > 3600:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_timeout_seconds must be between 0 and 3600.")
    if requests_per_minute_limit is not None:
        if not isinstance(requests_per_minute_limit, int):
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer.")
        if requests_per_minute_limit < 1 or requests_per_minute_limit > 6000:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 6000.")
    if concurrent_exec_limit is not None:
        if not isinstance(concurrent_exec_limit, int):
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "concurrent_exec_limit must be an integer.")
        if concurrent_exec_limit < 1 or concurrent_exec_limit > 256:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "concurrent_exec_limit must be between 1 and 256.")

    # Apply updates (must have at least one mutable field)
    mutable_present = any(v is not None for v in [name, status, allowed_commands, base_directory, max_timeout_seconds, requests_per_minute_limit, concurrent_exec_limit])
    if not mutable_present:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No mutable fields provided to update.")

    updated = dict(target)
    if name is not None:
        updated["name"] = name
    if status is not None:
        updated["status"] = status
    if allowed_commands is not None:
        updated["allowed_commands"] = allowed_commands
    if base_directory is not None:
        updated["base_directory"] = base_directory
    if max_timeout_seconds is not None:
        updated["max_timeout_seconds"] = max_timeout_seconds
    if requests_per_minute_limit is not None:
        updated["requests_per_minute_limit"] = requests_per_minute_limit
    if concurrent_exec_limit is not None:
        updated["concurrent_exec_limit"] = concurrent_exec_limit

    updated["updated_at"] = now
    api_keys[target_idx] = updated
    _save("api_keys.json", api_keys)

    _log("ok", caller.get("id"), None)
    return {
        "api_key": {
            "id": updated.get("id"),
            "name": updated.get("name"),
            "status": updated.get("status"),
            "allowed_commands": updated.get("allowed_commands"),
            "base_directory": updated.get("base_directory"),
            "max_timeout_seconds": updated.get("max_timeout_seconds"),
            "requests_per_minute_limit": updated.get("requests_per_minute_limit"),
            "concurrent_exec_limit": updated.get("concurrent_exec_limit"),
            "created_at": updated.get("created_at"),
            "updated_at": updated.get("updated_at"),
            "last_used_at": updated.get("last_used_at"),
        }
    }

def shell_executions_list(api_key, api_key_id=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0326000" if __import__("os").path.isdir("./environment_mix/0326000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")
    executions = _load("shell_executions.json")

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    caller = None
    for r in api_keys:
        if r.get("id") == api_key:
            caller = r
            break
    if caller is None:
        h = _hash_token(api_key)
        for r in api_keys:
            if r.get("key_hash") == h:
                caller = r
                break

    def _log(status_str, key_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "shell_executions_list",
            "api_key_id": key_id,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    if caller is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller.get("status") != "active":
        _log("error", caller.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    allowed_status = {"queued", "running", "succeeded", "failed", "timed_out", "rejected", "cancelled"}
    if status is not None and status not in allowed_status:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id):
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string.")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            raise ValueError("bad")
        if s.endswith("Z"):
            s2 = s[:-1] + "+00:00"
        else:
            s2 = s
        return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)

    try:
        ca = _parse_rfc3339(created_after) if created_after is not None else None
        cb = _parse_rfc3339(created_before) if created_before is not None else None
    except Exception:
        _log("error", caller.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after/created_before must be RFC 3339 timestamps.")

    # Cursor is base64-encoded JSON: {"created_at": "...", "id": "..."}
    cur_created = None
    cur_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        try:
            payload = json.loads(base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8"))
            cur_created = payload.get("created_at")
            cur_id = payload.get("id")
            if not isinstance(cur_created, str) or not isinstance(cur_id, str):
                raise ValueError("bad cursor")
        except Exception:
            _log("error", caller.get("id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Authorization: only list executions owned by caller key (no cross-key access)
    if api_key_id is None:
        api_key_id = caller.get("id")
    if api_key_id != caller.get("id"):
        _log("error", caller.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to list executions for another API key.")

    # Filter
    rows = []
    for e in executions if isinstance(executions, list) else []:
        if e.get("api_key_id") != api_key_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        e_created = e.get("created_at")
        if not isinstance(e_created, str):
            continue
        try:
            e_dt = _parse_rfc3339(e_created)
        except Exception:
            continue
        if ca is not None and not (e_dt > ca):
            continue
        if cb is not None and not (e_dt < cb):
            continue
        rows.append(e)

    # Sort newest first: created_at desc, id desc
    def _sort_key(e):
        return (e.get("created_at") or "", e.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly "before" the cursor in the same ordering
    if cur_created is not None and cur_id is not None:
        filtered = []
        for e in rows:
            ec = e.get("created_at") or ""
            eid = e.get("id") or ""
            if (ec, eid) < (cur_created, cur_id):
                filtered.append(e)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", caller.get("id"), None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0326000" if __import__("os").path.isdir("./environment_mix/0326000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    api_keys = _load("api_keys.json")
    counters = _load("rate_limit_counters.json")

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    caller = None
    for r in api_keys:
        if r.get("id") == api_key:
            caller = r
            break
    if caller is None:
        h = _hash_token(api_key)
        for r in api_keys:
            if r.get("key_hash") == h:
                caller = r
                break

    def _log(status_str, key_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "whoami",
            "api_key_id": key_id,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    if caller is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller.get("status") != "active":
        _log("error", caller.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.", status=caller.get("status"))

    # Update last_used_at on successful auth
    updated = False
    for i, r in enumerate(api_keys):
        if r.get("id") == caller.get("id"):
            api_keys[i] = dict(r)
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = now
            caller = api_keys[i]
            updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    # Rate-limit window consumption (60s window starting at minute)
    window_start_dt = now_dt.replace(second=0, microsecond=0)
    window_start = window_start_dt.isoformat() + "Z"
    window_seconds = 60
    current_counter = None
    for c in counters if isinstance(counters, list) else []:
        if c.get("api_key_id") == caller.get("id") and c.get("window_seconds") == window_seconds and c.get("window_start") == window_start:
            current_counter = c
            break

    request_count = current_counter.get("request_count") if isinstance(current_counter, dict) else 0
    rejected_count = current_counter.get("rejected_count") if isinstance(current_counter, dict) else 0
    limit = caller.get("requests_per_minute_limit")

    entitlements = {
        "can_shell_execute": True,
        "allowed_commands": caller.get("allowed_commands", []),
        "base_directory": caller.get("base_directory"),
        "max_timeout_seconds": caller.get("max_timeout_seconds"),
        # Key management: conservative, only self-update supported by api_keys_update implementation
        "can_manage_keys": "self_only"
    }

    _log("ok", caller.get("id"), None)
    return {
        "identity": {
            "api_key_id": caller.get("id"),
            "name": caller.get("name"),
            "status": caller.get("status"),
            "created_at": caller.get("created_at"),
            "updated_at": caller.get("updated_at"),
            "last_used_at": caller.get("last_used_at"),
        },
        "entitlements": entitlements,
        "rate_limit": {
            "window_seconds": window_seconds,
            "window_start": window_start,
            "requests_per_minute_limit": limit,
            "request_count": request_count,
            "rejected_count": rejected_count,
            "remaining": None if not isinstance(limit, int) else max(0, limit - int(request_count))
        }
    }
